UPDATE landings SET text_sr = 'Polovni Volkswagen je među najtraženijim automobilima u Srbiji: Golf svih generacija, Polo za grad, Passat i Touran za porodicu, Tiguan među SUV modelima i Caddy za posao. Ponuda je velika, pa je suzite po gradu, ceni i tome da li oglašava vlasnik ili auto-plac. Istu tehniku, često uz nižu cenu, imaju [Škoda](/oglasi/vozila/automobili/skoda) i [Seat](/oglasi/vozila/automobili/seat).

